import subprocess


def run(input):
    wt, branch = input["wt"], input["branch"]
    land_base = input.get("land_base") or "HEAD"
    base_branch = land_base.split("/", 1)[1] if "/" in land_base else "main"
    repo = input.get("repo") or wt

    def git(*a):
        return subprocess.run(["git", "-C", wt] + list(a),
                              capture_output=True, text=True)

    git("fetch", "origin")
    # 护栏（绝不代推他人提交）：本地 clone 的 <base> 领先 origin 的提交若
    # 出现在待落地集合里，说明本分支捆绑了本地未推工作 → 拒推交人工。
    # 本地与 origin 持平时护栏自然放行（自愈，无需人工改分支）。
    if land_base != "HEAD":
        loc = subprocess.run(["git", "-C", repo, "rev-list",
                              "origin/" + base_branch + ".." + base_branch],
                             capture_output=True, text=True).stdout.split()
        to_land = set(git("rev-list", land_base + "..HEAD").stdout.split())
        bundled = [c for c in loc if c in to_land]
        if bundled:
            return {"ok": False, "refuse": True, "note": "",
                    "why": "分支捆绑本地未推提交 %d 条，已拒推（交人工）：%s" % (
                        len(bundled), " ".join(bundled[:8]))}
    # 推分支（先删远端同名旧分支：rebase 后续推会分叉被拒，best-effort）
    git("push", "origin", "--delete", branch)
    r1 = git("push", "-u", "origin", branch)
    if r1.returncode != 0:
        return {"ok": False, "refuse": False, "note": "",
                "why": ("push branch: " + (r1.stderr or r1.stdout))[-400:]}
    # 直推基线：服务端 ff 校验；非 ff（基支已前进）→ ok=False 走 rebase 重试
    r2 = git("push", "origin", "HEAD:" + base_branch)
    if r2.returncode == 0:
        return {"ok": True, "refuse": False,
                "note": "已直推 " + base_branch + "（分支 " + branch + "）",
                "why": ""}
    return {"ok": False, "refuse": False, "note": "",
            "why": ("push " + base_branch + ": " + (r2.stderr or r2.stdout))[-400:]}

import subprocess


def run(input):
    wt = input["wt"]

    def git(*a):
        return subprocess.run(["git", "-C", wt] + list(a),
                              capture_output=True, text=True)

    git("fetch", "origin")
    r = git("rebase", "origin/main")
    if r.returncode != 0:
        # 冲突现场留在 worktree（不 abort），交当轮修复环就地解
        NL = "\n"
        st = git("status", "--short").stdout.strip()
        uf = git("diff", "--name-only", "--diff-filter=U").stdout.strip()
        df = git("diff").stdout
        lg = git("log", "--oneline", "origin/main..HEAD").stdout.strip()
        scene = NL.join(["git status --short", st, "", "unmerged files", uf,
                         "", "conflict diff", df[:6000], "",
                         "origin/main..HEAD", lg[-2000:]])
        return {"ok": False, "scene": scene,
                "why": ((r.stderr or "") + (r.stdout or ""))[-400:]}
    git("push", "origin", "--delete", input["branch"])
    return {"ok": True, "scene": "", "why": ""}

